function f(n){if(n._ribbonPolygons)return n._ribbonPolygons;if(n.shape!=="brick")return[];if(n.curveSlices?.length>=2){let a=n.height/2,m=[];for(let e=1;e<n.curveSlices.length;e++){let h=n.curveSlices[e-1],r=n.curveSlices[e];m.push([[h.x+h.nx*a,h.y+h.ny*a],[r.x+r.nx*a,r.y+r.ny*a],[r.x-r.nx*a,r.y-r.ny*a],[h.x-h.nx*a,h.y-h.ny*a]]);let x=r.x-h.x,s=r.y-h.y,y=Math.hypot(x,s);if(y>1e-6){let u=-s/y*a,p=x/y*a;m.push([[h.x+u,h.y+p],[r.x+u,r.y+p],[r.x-u,r.y-p],[h.x-u,h.y-p]])}}return m}let t=Math.cos(n.angle),i=Math.sin(n.angle);return[[[-1,-1],[1,-1],[1,1],[-1,1]].map(([a,m])=>[n.x+a*n.width/2*t-m*n.height/2*i,n.y+a*n.width/2*i+m*n.height/2*t])]}function M(n){if(n._ribbonBounds)return n._ribbonBounds;if(n.shape==="circle")return{minX:n.x-n.radius,maxX:n.x+n.radius,minY:n.y-n.radius,maxY:n.y+n.radius};let t=f(n).flat();return{minX:Math.min(...t.map(i=>i[0])),maxX:Math.max(...t.map(i=>i[0])),minY:Math.min(...t.map(i=>i[1])),maxY:Math.max(...t.map(i=>i[1]))}}function X(n){if(!n.length)return{minX:0,maxX:0,minY:0,maxY:0,width:0,height:0};let t=n.map(M),i={minX:Math.min(...t.map(a=>a.minX)),maxX:Math.max(...t.map(a=>a.maxX)),minY:Math.min(...t.map(a=>a.minY)),maxY:Math.max(...t.map(a=>a.maxY))};return{...i,width:i.maxX-i.minX,height:i.maxY-i.minY}}function c(n){return n.map((t,i)=>{let a=n[(i+1)%n.length],m=a[0]-t[0],e=a[1]-t[1],h=Math.hypot(m,e)||1;return[-e/h,m/h]})}function o(n,t){let i=1/0;for(let a of[...c(n),...c(t)]){let m=x=>x.map(s=>s[0]*a[0]+s[1]*a[1]),e=m(n),h=m(t),r=Math.min(Math.max(...e),Math.max(...h))-Math.max(Math.min(...e),Math.min(...h));if(r<=0)return r;i=Math.min(i,r)}return i}function d(n,t){let i=c(t),a=t[0];for(let x of t)Math.hypot(x[0]-n.x,x[1]-n.y)<Math.hypot(a[0]-n.x,a[1]-n.y)&&(a=x);let m=a[0]-n.x,e=a[1]-n.y,h=Math.hypot(m,e);h>1e-9&&i.push([m/h,e/h]);let r=1/0;for(let x of i){let s=t.map(p=>p[0]*x[0]+p[1]*x[1]),y=n.x*x[0]+n.y*x[1],u=Math.min(Math.max(...s),y+n.radius)-Math.max(Math.min(...s),y-n.radius);if(u<=0)return u;r=Math.min(r,u)}return r}function l(n,t){if(n.shape==="circle"&&t.shape==="circle")return n.radius+t.radius-Math.hypot(n.x-t.x,n.y-t.y);if(t.shape==="circle")return l(t,n);let i=M(n),a=M(t);return i.maxX<=a.minX||a.maxX<=i.minX||i.maxY<=a.minY||a.maxY<=i.minY?-1:n.shape==="circle"?Math.max(...f(t).map(m=>d(n,m))):Math.max(...f(n).flatMap(m=>f(t).map(e=>o(m,e))))}function Y(n,t=[n.x,n.y]){return n.shape==="circle"?Math.hypot(n.x-t[0],n.y-t[1])+n.radius:Math.max(...f(n).flat().map(i=>Math.hypot(i[0]-t[0],i[1]-t[1])))}export{M as a,X as b,l as c,Y as d};
